/* Editorial learning content. Personal achievements are never pre-populated. */
const STAGES = [
{id:'s0',n:'00',title:'Prepare your lab',short:'Set a safe starting point',desc:'Establish a repeatable lab, then map what you already know and what needs practice.',topics:['Isolation','Baseline','Evidence'],labs:['readiness','baseline'],gate:'Save your environment baseline and a snapshot. Record C, assembly, and debugger confidence without assuming proficiency.',bridge:'Your digital forensics habits already provide the foundation: preserve provenance, record versions, and separate observation from interpretation.'},
{id:'s1',n:'01',title:'Understand C & memory',short:'Think below Python',desc:'Connect variables, pointers, and object lifetimes to concrete bytes in memory.',topics:['Pointers','Stack & heap','Integers'],labs:['memory','bounds'],gate:'Explain a pointer, array boundary, and object lifetime. Compile your own small C program and identify a bounds error.',bridge:'Python is a strong analysis language. Use it to inspect bytes and automate evidence collection while you learn C’s explicit memory model.'},
{id:'s2',n:'02',title:'Read the machine',short:'From source to instructions',desc:'Read small x86-64 functions and explain branches, registers, and calling conventions.',topics:['x86-64','Control flow','ABI'],labs:['branch','abi'],gate:'Annotate a small function and predict two branches. State the architecture, ABI, compiler, and optimization level.',bridge:'The same discipline you use to interpret event sequences applies to instruction traces. Each observation needs its execution context.'},
{id:'s3',n:'03',title:'Investigate a binary',short:'Static meets dynamic',desc:'Move between file structures, disassembly, decompilation, and debugger observations.',topics:['PE / ELF','Ghidra','GDB'],labs:['static','debug'],gate:'Produce a function map and confirm one decompiler hypothesis in a debugger. Preserve an alternative explanation.',bridge:'Your Windows log experience helps connect imported APIs and observed process behavior. An import is a clue, never proof of execution.'},
{id:'s4',n:'04',title:'Research a weakness',short:'Find, explain, repair',desc:'Triage a controlled memory error in a toy parser and verify a defensive correction.',topics:['Sanitizers','Root cause','Regression'],labs:['triage','repair'],gate:'Reproduce a toy-program defect, locate its cause, repair it, and rerun valid and invalid inputs. Do not infer exploitability from a crash.',bridge:'Reuse your research workflow: controlled inputs, reproducible experiments, competing explanations, and bounded conclusions.'},
{id:'s5',n:'05',title:'Connect & document',short:'Turn evidence into insight',desc:'Relate a benign binary to telemetry, then write a defensible project record.',topics:['Telemetry','Evidence graph','Portfolio'],labs:['telemetry','report'],gate:'Publish a local report with hashes, tool versions, reproduction steps, supporting evidence, limitations, and a clean rerun.',bridge:'Bring together Security Onion, Windows events, Neo4j, identity context, and forensic reasoning. Make each graph relationship traceable to a source.'},
{id:"s6",n:"06",title:"Automate the analysis",short:"From one binary to a pipeline",desc:"Let tools generate inputs, measure what they reached, solve path conditions and answer graph questions, while you stay responsible for the claims.",topics:["Fuzzing","Coverage","Symbolic execution","Program graphs"],labs:["fuzz","coverage","symbolic","callgraph"],gate:"Run a bounded fuzzing campaign on an owned target, report coverage from repeated trials, obtain one input from a solver and confirm it on the real binary, and answer one reachability question with an explicit unknown where the graph is incomplete.",bridge:"Your thesis asked which identities can reach which resources. A call graph asks which entry points can reach which functions. The graph reasoning carries over; the edges now come from instructions instead of authentication telemetry."},
{id:"s7",n:"07",title:"Engineer for industry",short:"Design, evaluate, deploy",desc:"Turn analysis techniques into something an organization can run: audits that scale, patch verification, triage that people can act on, and a design proposal with a validation plan.",topics:["Hardening audit","Patch verification","Triage at scale","Design proposal"],labs:["hardening","patchdiff","crashtriage","proposal"],gate:"Produce a hardening inventory with unknowns preserved, verify a repair at binary level, reduce a crash set to analyst-reviewed buckets, and write a design brief whose requirements can each be tested.",bridge:"Five years of network and systems administration is the asset here. You know what an operations team will actually run, what breaks a deployment, and what a small organization cannot afford. An engineering doctorate is assessed on that fit as much as on the technique."}
];
const SOURCE_BRANCH = `#include <stdio.h>\nint classify(unsigned int value) {\n    if (value < 16) return 1;\n    return 0;\n}\nint main(void) {\n    printf("%d %d\\n", classify(15), classify(16));\n    return 0;\n}\n`;
const SOURCE_MEMORY = `#include <stdio.h>\nint main(void) {\n    unsigned char bytes[4] = {0x41, 0x42, 0x43, 0x00};\n    unsigned char *p = bytes;\n    printf("first=%u second=%u size=%zu\\n", p[0], p[1], sizeof(bytes));\n    return 0;\n}\n`;
const SOURCE_PARSER = `/* Deliberately flawed, locally owned teaching program.\n   Run only in your isolated learning VM. */\n#include <stddef.h>\n#include <stdio.h>\nint parse(const unsigned char *buf, size_t size) {\n    if (size == 0) return -1;\n    size_t length = buf[0];\n    /* Teaching defect: length is not checked against size. */\n    unsigned int total = 0;\n    for (size_t i = 0; i < length; ++i) total += buf[i + 1];\n    return (int)total;\n}\nint main(void) {\n    const unsigned char valid[] = {2, 10, 20};\n    const unsigned char truncated[] = {3, 10};\n    printf("valid=%d\\n", parse(valid, sizeof(valid)));\n    printf("truncated=%d\\n", parse(truncated, sizeof(truncated)));\n    return 0;\n}\n`;
const SOURCE_TLV = "/* Deliberately flawed, locally owned teaching program.\n   Run only in your isolated learning VM.\n   Record: magic \"ATLS\" (4) | type (1) | len (1) | payload (len)\n   Builds: default = file reader, -DFUZZ = libFuzzer harness,\n           -DFIX_A / -DFIX_B = repair one teaching defect,\n           -DFIXED = repair both. */\n#include <stddef.h>\n#include <stdint.h>\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\n#ifdef FIXED\n#define FIX_A\n#define FIX_B\n#endif\n\nint tlv_parse(const uint8_t *buf, size_t size) {\n    if (size < 6) return -1;\n    if (memcmp(buf, \"ATLS\", 4) != 0) return -2;\n    uint8_t type = buf[4];\n    size_t len = buf[5];\n    const uint8_t *payload = buf + 6;\n    switch (type) {\n    case 1: { /* checksum record */\n#ifdef FIX_A\n        if (len > size - 6) return -3;\n#endif\n        /* Teaching defect A: len is not checked against size. */\n        unsigned int total = 0;\n        for (size_t i = 0; i < len; ++i) total += payload[i];\n        return (int)(total & 0x7fff);\n    }\n    case 2: { /* label record */\n        uint8_t label[8] = {0};\n        if (len > size - 6) return -3;\n#ifdef FIX_B\n        if (len > sizeof(label)) return -4;\n#endif\n        /* Teaching defect B: len is not checked against the label size. */\n        memcpy(label, payload, len);\n        return label[0];\n    }\n    case 3: { /* version record guarded by an arithmetic condition */\n        if (len != 4 || size - 6 < 4) return -3;\n        uint32_t v;\n        memcpy(&v, payload, 4);\n        if (((v ^ 0x5a5a5a5au) * 2654435761u) >> 7 == 0xddd54au) return 0x7777; /* gated path */\n        return 0;\n    }\n    default:\n        return -5;\n    }\n}\n\n#ifdef FUZZ\nint LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {\n    /* Keep the result alive so the optimizer cannot delete the call. */\n    static volatile int sink;\n    sink = tlv_parse(data, size);\n    return 0;\n}\n#else\nint main(int argc, char **argv) {\n    if (argc != 2) { fprintf(stderr, \"usage: %s <record-file>\\n\", argv[0]); return 2; }\n    FILE *f = fopen(argv[1], \"rb\");\n    if (!f) { perror(\"fopen\"); return 2; }\n    uint8_t *buf = malloc(4096);\n    if (!buf) { fclose(f); return 2; }\n    size_t n = fread(buf, 1, 4096, f);\n    fclose(f);\n    /* Copy into an exact-size allocation so a sanitizer sees the real bound. */\n    uint8_t *exact = malloc(n ? n : 1);\n    if (!exact) { free(buf); return 2; }\n    memcpy(exact, buf, n);\n    free(buf);\n    printf(\"result=%d\\n\", tlv_parse(exact, n));\n    free(exact);\n    return 0;\n}\n#endif\n";
const SOURCE_REACH = "/* Locally owned teaching program for call-graph reachability.\n   legacy_decode holds the \"weakness\" a scanner would flag. Is it reachable? */\n#include <stdio.h>\n#include <string.h>\n\ntypedef int (*handler_fn)(const char *);\n\n__attribute__((noinline)) int legacy_decode(const char *text) { return (int)strlen(text) * 2; }\n__attribute__((noinline)) int modern_decode(const char *text) { return (int)strlen(text); }\n__attribute__((noinline)) int audit_log(const char *text) { return printf(\"audit: %s\\n\", text); }\n__attribute__((noinline)) int unused_export(const char *text) { return legacy_decode(text); }\n__attribute__((noinline)) int plugin_entry(const char *text) { return legacy_decode(text) + 1; }\n\nstatic handler_fn handlers[] = { modern_decode, plugin_entry };\n\n__attribute__((noinline)) int dispatch(unsigned int kind, const char *text) {\n    if (kind >= sizeof(handlers) / sizeof(handlers[0])) return -1;\n    return handlers[kind](text); /* indirect call: target unknown to a direct-call graph */\n}\n\nint main(int argc, char **argv) {\n    const char *text = argc > 1 ? argv[1] : \"atlas\";\n    audit_log(text);\n    printf(\"%d\\n\", dispatch(argc > 2, text));\n    return 0;\n}\n";
const LABS = [
{id:'readiness',stage:'s0',title:'Map your starting point',time:25,level:'Orientation',type:'Reflection',objective:'Record your current knowledge without turning prior cybersecurity experience into assumed low-level proficiency.',steps:['List one concrete task you have completed with Python, Windows event logs, Security Onion, Neo4j, digital forensics, and identity security. Add an evidence reference if available.','For C, pointers, assembly, debuggers, and PE/ELF, record: not tried / learning / independently practiced. Unknown is a valid answer.','Pick one knowledge gap and a weekly study time that fits your schedule. The suggested lab durations are estimates, not deadlines.'],evidence:['A dated baseline note','One learning question','Your own availability estimate'],resource:'ost2',outcome:'A clear baseline and a learning question you can revisit.'},
{id:'baseline',stage:'s0',title:'Create a reproducible lab baseline',time:40,level:'Foundation',type:'Lab setup',objective:'Build an isolated environment for your own benign C programs and make it recoverable.',steps:['Work through the Lab setup checklist. Choose a Linux VM for the first C/GDB exercises. A later Windows VM is optional for PE and event correlation.','Record host architecture, guest OS, compiler, debugger, and tool versions. If your host uses ARM, select an appropriate x86-64 environment or record an architecture change; these exercises assume x86-64.','Install from official sources, then take a clean snapshot. Disconnect networking before program execution. Record the snapshot name and date.'],evidence:['Environment and version inventory','Network mode and isolation notes','A named clean snapshot'],resource:'gdb',outcome:'A documented environment you can restore.'},
{id:'memory',stage:'s1',title:'Follow four bytes through C',time:35,level:'Foundation',type:'Hands-on',objective:'Explain the difference between an array, a pointer, and the bytes a program reads.',steps:['Download memory.c and read it before compiling. Predict the two printed values and the array size.','In your lab VM, compile with debug symbols using the command below. Run your own program and compare your prediction.','Draw the four bytes, then change a value safely within the array. Explain why a pointer does not carry the array length.'],evidence:['Source hash and compiler version','Predicted and observed output','A memory sketch with array bounds'],resource:'ce',source:SOURCE_MEMORY,filename:'memory.c',commands:'cc -g -O0 -Wall -Wextra memory.c -o memory\n./memory\nsha256sum memory.c memory',outcome:'A four-byte memory sketch supported by observed output.'},
{id:'bounds',stage:'s1',title:'Reason about lengths & lifetimes',time:40,level:'Foundation',type:'Code review',objective:'Identify which data is valid to access and which assumptions need explicit checks.',steps:['Use memory.c from the previous exercise. Explain why indexes 0 through 3 are valid and index 4 is outside the array. Do not perform the invalid read in this exercise.','Write a checked accessor that accepts a pointer, a size, and an index and rejects an index outside the range.','Review signed versus unsigned comparisons and local object lifetimes. Record one uncertainty and look it up before marking this complete.'],evidence:['A checked accessor with boundary tests','A lifetime explanation','An unresolved question or a source-supported resolution'],resource:'cmanual',outcome:'A small bounds-checked function and an explicit ownership explanation.'},
{id:'branch',stage:'s2',title:'Read your first branch',time:45,level:'Foundation',type:'Hands-on',objective:'Connect a C condition to machine instructions and verify the boundary input.',steps:['Download branch.c. Predict the results for values 15 and 16, then compile with debug symbols and no optimization.','Disassemble classify. Identify the compare, conditional branch, and return value. Your compiler output may differ from the illustrative trace in the workspace.','Recompile at -O2. Explain any change in instruction selection or inlining. Keep the compiler, target, ABI, and flags with both observations.'],evidence:['Annotated disassembly for your exact build','Boundary input observations','A comparison of -O0 and -O2 with limitations'],resource:'ost2',source:SOURCE_BRANCH,filename:'branch.c',commands:'cc -g -O0 -Wall -Wextra branch.c -o branch\n./branch\nobjdump -d -M intel branch\ncc -g -O2 branch.c -o branch-o2',outcome:'An annotated branch with a verified boundary condition.'},
{id:'abi',stage:'s2',title:'Trace a function call',time:40,level:'Developing',type:'Debugger',objective:'Observe arguments and return values under a named ABI.',steps:['Use your own branch.c build. In Linux x86-64 System V, start by inspecting the first integer argument in edi and the integer result in eax. This differs from Windows x64, whose first integer argument uses ecx.','Break at classify, inspect registers, step, and record how the return value reaches the caller. Optimization may inline or remove the call; use the -O0 build.','Create a tiny second function with two arguments. Record which registers you observe rather than applying one ABI to every platform.'],evidence:['Architecture and ABI label','A register trace for one call','One ABI-specific limitation'],resource:'intel',outcome:'A call trace with context sufficient for another learner to reproduce it.'},
{id:'static',stage:'s3',title:'Build a small function map',time:55,level:'Developing',type:'Static analysis',objective:'Distinguish file metadata, disassembly, and decompiler interpretation.',steps:['Import your own branch binary into Ghidra after confirming the target and file format. Keep its hash and build settings.','Find main and classify. Rename one symbol, annotate the branch, and compare decompiler output with instructions.','Inspect imports and strings. Write one hypothesis and an alternative explanation. Static presence alone does not establish runtime behavior.'],evidence:['Binary SHA-256 and import settings','Annotated function map','A hypothesis and an alternative'],resource:'ghidra',outcome:'A small map that separates observations from inferred behavior.'},
{id:'debug',stage:'s3',title:'Test a static hypothesis in GDB',time:50,level:'Developing',type:'Debugger',objective:'Use dynamic evidence to confirm a specific claim about your own program.',steps:['Open the same hashed branch build with GDB. Set a breakpoint at classify and choose a known input.','Inspect the argument, step through the comparison, and record the result. Repeat with the boundary input on the other side.','Compare runtime evidence with your Ghidra hypothesis. State what you did not observe. Addresses may change between runs and builds.'],evidence:['Debugger version and commands','Two input/output observations','A claim revised or supported by execution'],resource:'gdb',commands:'gdb ./branch\n# Inside GDB:\nbreak classify\nrun\ninfo registers\ndisassemble classify\nnexti\ncontinue',outcome:'A hypothesis supported by two controlled observations.'},
{id:'triage',stage:'s4',title:'Triage a toy parser bounds error',time:60,level:'Intermediate',type:'Vulnerability research',objective:'Locate and explain an out-of-bounds read in a deliberately flawed program you own.',steps:['Read parser_lab.c. Identify the length-prefix assumption before running anything. Use only your isolated lab.','Compile with AddressSanitizer and run the fixed built-in test inputs. Capture the diagnostic and build context. Exact messages depend on your toolchain.','Trace the diagnostic to the unchecked length. Explain why a crash or sanitizer report is evidence of a defect but does not by itself establish exploitability or real-world impact.'],evidence:['Source and binary hashes','A sanitizer diagnostic with versions','Root cause with bounded impact claims'],resource:'asan',source:SOURCE_PARSER,filename:'parser_lab.c',commands:'clang -g -O1 -fsanitize=address -fno-omit-frame-pointer parser_lab.c -o parser_lab\n./parser_lab',outcome:'A reproducible defect report for a controlled teaching program.'},
{id:'repair',stage:'s4',title:'Repair & regression-test the parser',time:65,level:'Intermediate',type:'Defensive engineering',objective:'Show that a bounds check rejects truncation while preserving valid behavior.',steps:['After the size == 0 check, reject length > size - 1. Keep the unsigned arithmetic safe by retaining that initial size check. Save the repaired source separately.','Repeat the valid and truncated cases under the sanitizer. Add empty input, a zero-length record, an exact-length record, and an over-declared length.','Record expected and observed results. A clean sanitizer run covers these inputs only. As an optional next step, read the official libFuzzer guide and design a bounded harness for this owned parser.'],evidence:['The minimal source diff','Regression input/output table','Remaining coverage gaps'],resource:'fuzzer',outcome:'A minimal repair, test table, and explicit coverage limits.'},
{id:'telemetry',stage:'s5',title:'Connect binary behavior to telemetry',time:75,level:'Synthesis',type:'Forensic bridge',objective:'Relate one observed benign program action to a source-backed event without overstating causality.',steps:['In an optional isolated Windows lab, compile a benign program that opens a local text file. Record source, binary hash, time zone, and execution time. Do not assume the Linux sample produces Windows telemetry.','Choose available logs and document the audit policy and collection configuration. Event 4624 concerns logon context; it does not prove a function call, file access, or malicious behavior. Process telemetry availability depends on configuration.','If your isolated monitoring lab includes Security Onion, correlate only the records actually collected. In Neo4j, label evidence-derived relationships separately from hypotheses and preserve source record references.'],evidence:['Lab and telemetry collection configuration','Timestamped source event references','An evidence graph with alternative explanations'],resource:'event4624',outcome:'A bounded behavior-to-event correlation, or an honest record of missing telemetry.'},
{id:'report',stage:'s5',title:'Write an evidence-led project report',time:60,level:'Synthesis',type:'Portfolio',objective:'Turn a completed investigation into a reproducible and appropriately scoped portfolio entry.',steps:['Choose a project you actually completed. Use the Portfolio section to create a draft. Suggested projects are ideas until you add your own work.','Record your question, scope and authorization, sample/source provenance, SHA-256 values, tools, reproduction steps, observations, and limitations. Redact personal data.','Perform a clean rerun. Only mark the entry self-verified when the required evidence exists and you have checked it. This is your attestation, not independent validation.'],evidence:['A complete report and evidence references','A clean reproduction result','Limitations and verification date'],resource:'ghidra',outcome:'A reviewable project entry with honest verification status.'},
{id:"fuzz",stage:"s6",title:"Fuzz an owned parser with a time budget",time:75,level:"Intermediate",type:"Automated testing",objective:"Run a coverage-guided fuzzer against a deliberately flawed record parser and learn why fixing one defect reveals the next.",steps:["Read tlv_lab.c first. Write down the record format, the two teaching defects (A and B) and the gated path in record type 3. Note the volatile sink in the harness: without it the optimizer may delete the call under test, and the fuzzer would report runs that test nothing.","Build the harness and fuzz with a fixed time budget and a recorded seed. Keep the crash file, the sanitizer summary and the exact command. Then rebuild with -DFIX_A and fuzz again: a second, different defect should become visible. Record how long each took in your run; do not copy times from anywhere else.","Rebuild with -DFIXED and run the same budget. A run without crashes covers that budget, that seed and that harness only. Write one sentence on what the campaign did not exercise."],evidence:["Compiler and libFuzzer version, flags, seed and time budget for every run","Crash inputs with SHA-256 and the sanitizer summary line for defects A and B","A statement of what the clean run does and does not show"],resource:"fuzzer",source:SOURCE_TLV,filename:"tlv_lab.c",commands:"mkdir -p corpus crashes\nprintf 'ATLS\\x01\\x02\\x0a\\x14' > corpus/seed-valid\nclang -g -O1 -DFUZZ -fsanitize=fuzzer,address -fno-omit-frame-pointer tlv_lab.c -o tlv_fuzz\n./tlv_fuzz corpus -seed=1 -max_total_time=60 -artifact_prefix=crashes/\n# Repair defect A only, then look for what it was hiding:\nclang -g -O1 -DFUZZ -DFIX_A -fsanitize=fuzzer,address -fno-omit-frame-pointer tlv_lab.c -o tlv_fuzz_a\n./tlv_fuzz_a corpus -seed=1 -max_total_time=60 -artifact_prefix=crashes/\n# Both repaired:\nclang -g -O1 -DFUZZ -DFIXED -fsanitize=fuzzer,address -fno-omit-frame-pointer tlv_lab.c -o tlv_fuzz_fixed\n./tlv_fuzz_fixed corpus -seed=1 -max_total_time=60",outcome:"Two reproducible crash inputs with distinct causes, and a bounded statement about the repaired build."},
{id:"coverage",source:SOURCE_TLV,filename:"tlv_lab.c",stage:"s6",title:"Measure what the fuzzer reached",time:60,level:"Intermediate",type:"Evaluation",objective:"Replace \"it ran for a minute\" with a coverage measurement from repeated trials, and find the code the campaign never executed.",steps:["Build the repaired harness with source-based coverage. Run at least three trials that differ only in the seed, each into its own empty corpus directory and its own profile file.","Produce a coverage report per trial. Record line, region and branch coverage for each. Fuzzing is randomized: report every trial and the spread, never only the best one.","Open the annotated source and find the line with a zero count. Explain why random mutation rarely satisfies that condition. This uncovered line is the starting point for the symbolic execution exercise."],evidence:["Coverage table for at least three trials with seeds and budgets","The annotated source line that was not reached","A note on variance between trials and on what coverage cannot tell you"],resource:"cov",commands:"clang -g -O1 -DFUZZ -DFIXED -fsanitize=fuzzer -fprofile-instr-generate -fcoverage-mapping tlv_lab.c -o tlv_cov\nfor t in 1 2 3; do\n  mkdir -p trial$t\n  LLVM_PROFILE_FILE=trial$t.profraw ./tlv_cov trial$t -seed=$t -max_total_time=30\n  llvm-profdata merge -o trial$t.profdata trial$t.profraw\n  llvm-cov report ./tlv_cov -instr-profile=trial$t.profdata\ndone\nllvm-cov show ./tlv_cov -instr-profile=trial1.profdata tlv_lab.c",outcome:"A small, honest evaluation: repeated trials, reported spread, and a named coverage gap."},
{id:"symbolic",source:SOURCE_TLV,filename:"tlv_lab.c",stage:"s6",title:"Solve a path condition with symbolic execution",time:80,level:"Intermediate",type:"Program analysis",objective:"Ask a solver for an input that reaches the gated path the fuzzer missed, then confirm the answer on the real binary.",steps:["Create a Python virtual environment in your lab VM and install angr from the official package index while the network is still attached. Record the version: the API differs between major releases.","Read solve_gate.py before running it. It starts at tlv_parse with ten symbolic bytes, explores every path of this small function and asks whether any return value can equal the gated result. Build the plain target and run the script.","The solver output is a model, not an observation. Run the real binary on the generated file and record the actual result. Then write down why this worked here and would not scale unchanged: few paths, no loops over symbolic lengths, no system calls."],evidence:["angr version and the exact script invocation","The candidate input (hex) and the real binary’s output on it","Two limits of the approach, in your own words"],resource:"angr",files:["solve_gate.py"],commands:"python3 -m venv venv && venv/bin/pip install angr\ncc -g -O0 -DFIXED tlv_lab.c -o tlv_plain\nvenv/bin/python solve_gate.py ./tlv_plain gate.bin\n./tlv_plain gate.bin\nsha256sum tlv_plain gate.bin",outcome:"One solver-generated input, confirmed by execution, with the technique’s limits stated."},
{id:"callgraph",stage:"s6",title:"Answer a reachability question on a call graph",time:70,level:"Intermediate",type:"Graph analysis",objective:"Decide whether a flagged function can be reached from the program entry, and keep \"unknown\" as a legitimate answer when the graph is incomplete.",steps:["Read reach.c. legacy_decode stands for a function a scanner has flagged. Predict, from the source, whether main can reach it. Then build the binary and run callgraph.py with main as source and legacy_decode as target.","The script reports UNKNOWN, not \"unreachable\": dispatch contains an indirect call whose targets a direct-call graph cannot see. Resolve it with evidence: break on legacy_decode in GDB, run the program with one and with two arguments, and record which run reaches it.","Optional: export the graph with --cypher and load it into Neo4j. Add the edge you observed in the debugger as a separate relationship type with its evidence source, so recovered and observed edges stay distinguishable."],evidence:["Script output with the three-valued verdict","Debugger evidence that resolves the indirect call for specific inputs","A note on what static call graphs over- and under-approximate"],resource:"ghidragh",source:SOURCE_REACH,filename:"reach.c",files:["callgraph.py"],commands:"cc -g -O1 -Wall -Wextra reach.c -o reach\npython3 callgraph.py ./reach --source main --target legacy_decode\npython3 callgraph.py ./reach --source main --target audit_log\ngdb -batch -ex \"break legacy_decode\" -ex \"run\" -ex \"bt\" --args ./reach atlas\ngdb -batch -ex \"break legacy_decode\" -ex \"run\" -ex \"bt\" --args ./reach atlas second\npython3 callgraph.py ./reach --cypher graph.cypher",outcome:"A reachability verdict backed by static and dynamic evidence, with unresolved edges labelled."},
{id:"hardening",source:SOURCE_TLV,filename:"tlv_lab.c",stage:"s7",title:"Audit build hardening across binaries",time:55,level:"Intermediate",type:"Assurance",objective:"Produce a hardening inventory for a set of binaries and report missing evidence as unknown rather than as a pass or a fail.",steps:["Build tlv_lab.c twice: once with common hardening options and once with them disabled. Strip a copy of the hardened build. Predict which properties each binary will show.","Run hardening_audit.py on all three and on one system library. Compare with your prediction. Read the script to see which readelf fact supports each verdict, and where it answers unknown or \"not observed\".","Explain each property in one line for a non-specialist reader: what it makes harder, and what it does not prevent. A hardened build of a flawed parser still contains the flaw."],evidence:["Exact build commands and tool versions","The audit output (text or JSON) for every binary","A short plain-language explanation of each property and its limits"],resource:"openssf",files:["hardening_audit.py"],commands:"cc -O2 -fstack-protector-strong -D_FORTIFY_SOURCE=2 -fPIE -pie -Wl,-z,relro,-z,now tlv_lab.c -o tlv_hard\ncc -O0 -fno-stack-protector -no-pie -Wl,-z,norelro -z execstack tlv_lab.c -o tlv_soft\nstrip -o tlv_hard_stripped tlv_hard\npython3 hardening_audit.py tlv_hard tlv_soft tlv_hard_stripped\npython3 hardening_audit.py --json tlv_hard tlv_soft > inventory.json",outcome:"A reproducible hardening inventory that a reviewer can re-run, with unknowns preserved."},
{id:"patchdiff",source:SOURCE_TLV,filename:"tlv_lab.c",stage:"s7",title:"Verify a repair at binary level",time:60,level:"Intermediate",type:"Patch verification",objective:"Show from two binaries alone which function a fix changed, and connect the changed instructions to the source-level bounds check.",steps:["Build the flawed program and the build with defect A repaired, using identical compiler and flags. Record both hashes.","Run funcdiff.py. It should report exactly one changed function. Use --show to print the instruction-level difference and identify the added comparison and branch.","Rebuild the old source a second time and diff it against the first build to confirm the tool reports no change. Then change only the optimization level and observe how much \"changes\". State what this tells you about comparing vendor binaries built with unknown flags."],evidence:["Hashes and build commands for each binary","The function-level diff and your annotation of the added check","The control comparison (identical rebuild) and the flag-change comparison"],resource:"ghidragh",files:["funcdiff.py"],commands:"cc -g -O1 tlv_lab.c -o tlv_old\ncc -g -O1 -DFIX_A tlv_lab.c -o tlv_new\nsha256sum tlv_old tlv_new\npython3 funcdiff.py tlv_old tlv_new --show tlv_parse\ncc -g -O1 tlv_lab.c -o tlv_rebuild\npython3 funcdiff.py tlv_old tlv_rebuild\ncc -g -O2 tlv_lab.c -o tlv_o2\npython3 funcdiff.py tlv_old tlv_o2",outcome:"A binary-level confirmation that a specific fix is present, with a control and a stated limit."},
{id:"crashtriage",source:SOURCE_TLV,filename:"tlv_lab.c",stage:"s7",title:"Reduce crashes to reviewed buckets",time:70,level:"Intermediate",type:"Triage",objective:"Turn a directory of fuzzer crash files into a short list of distinct defects that an analyst has reviewed and classified.",steps:["Collect crash inputs from the fuzzing exercise: several from the flawed build and several from the build with only defect A repaired. Build the replay target with AddressSanitizer.","Run triage.py. It replays each file and groups them by error type, access type and top program frames. Compare the bucket count with the number of input files, and note the bucket for any file that produces no sanitizer report.","Fill the analyst columns of the CSV yourself: a CWE identifier you can justify from the root cause, the root cause in one sentence, and a priority with its reasoning. The script leaves these empty on purpose. Do not assign a severity score that implies reachability or impact you have not shown."],evidence:["The crash set with hashes and the replay build command","The bucket table before and after your analyst review","For each bucket: root cause, justified CWE, and what remains unknown"],resource:"cwe",files:["triage.py"],commands:"clang -g -O1 -fsanitize=address -fno-omit-frame-pointer tlv_lab.c -o tlv_asan\npython3 triage.py ./tlv_asan crashes --csv buckets.csv\ncat buckets.csv",outcome:"A reviewed triage table: many inputs, few defects, each with a stated root cause and open questions."},
{id:"proposal",stage:"s7",title:"Write a design brief for an industrial problem",time:120,level:"Synthesis",type:"Design proposal",objective:"Frame one candidate project as an engineering design problem with stakeholders, testable requirements and a validation plan.",steps:["Pick one direction from the EngD alignment page, or your own. Describe the problem context without the solution: who has the problem, what it costs them today, and what they do instead. Mark every statement you have not confirmed with a real stakeholder as an assumption.","Write requirements that can each be tested, including the operational ones your administration experience suggests: runtime budget, skills needed to operate it, failure behavior, and data that may not leave the organization. List at least two alternative designs and why you would reject them.","Plan the validation: what you will measure, on which targets, against which baseline, and what result would make you abandon the design. Add scope, authorization and disclosure handling. Use the design brief template in the repository and keep it as a draft until someone else has challenged it."],evidence:["A completed design brief with assumptions marked","A requirements table where each row names its test","A validation plan with a baseline and an abandonment criterion"],resource:"wieringa",outcome:"A design brief you could send to a prospective supervisor or company, with its unverified parts visible."}
];
