const CONCEPTS = [
{id:'bytes',title:'Bytes & endianness',category:'Foundations',desc:'A byte is eight bits. Endianness describes the order of bytes in a multi-byte value; it does not reverse the bits inside each byte.',example:'The value 0x12345678 appears as 78 56 34 12 in little-endian memory.',check:'Distinguish an address, the bytes stored there, and the numeric interpretation.',bridge:'Your Python byte parsing can make each representation explicit.',resource:'intel'},
{id:'pointers',title:'Pointers & object lifetime',category:'Foundations',desc:'A pointer identifies a location. Valid access also requires a live object, suitable type and alignment, and an in-bounds range.',example:'For unsigned char b[4], b[0] through b[3] are valid. b[4] is outside the array.',check:'Where did the object come from, how large is it, and when does it stop existing?',bridge:'Use the same scope discipline you apply to contextual identity claims.',resource:'asan'},
{id:'stack',title:'Stack, heap & ownership',category:'Foundations',desc:'Automatic local objects commonly use a stack, while dynamically allocated objects use allocator-managed memory. The language lifetime rules matter more than a simple location label.',example:'Returning a pointer to a local array leaves a pointer to an object whose lifetime has ended.',check:'Name the owner and the valid lifetime before drawing a memory map.',bridge:'Document ownership as explicitly as source provenance in a forensic case.',resource:'asan'},
{id:'registers',title:'Registers & calling conventions',category:'Machine code',desc:'Registers hold execution state. An ABI defines argument passing, return values, stack alignment, and preservation rules for a platform.',example:'First integer argument: edi under Linux x86-64 System V; ecx under Windows x64. Small integer return: eax.',check:'State the architecture and ABI before labeling a register as an argument.',bridge:'Environment context changes interpretation, just as it does for Windows events.',resource:'intel'},
{id:'flow',title:'Control flow & flags',category:'Machine code',desc:'Comparisons and arithmetic affect flags. Conditional instructions interpret those flags; signed and unsigned comparisons have different meanings.',example:'An unsigned value < 16 and a signed value < 16 can compile to different conditional branches.',check:'Identify operand width, signedness, and the predecessor that set the flags.',bridge:'An instruction trace is a sequence with causality, not a list of isolated events.',resource:'ost2'},
{id:'formats',title:'PE / ELF & loading',category:'Analysis',desc:'Executable formats describe headers, code and data regions, imports, and other loader-facing metadata. File offsets and virtual addresses are different coordinate systems.',example:'A string in a file or an imported API supports a hypothesis, but does not prove execution.',check:'Distinguish file metadata, mapped memory, and observed runtime behavior.',bridge:'PE analysis extends your Windows and forensic background.',resource:'pe'},
{id:'decompile',title:'Disassembly vs decompilation',category:'Analysis',desc:'Disassembly represents decoded instructions. Decompilation reconstructs a higher-level interpretation that may lose types, structure, or intent.',example:'An apparent array or signed variable in pseudocode may be an inferred type. Validate important assumptions.',check:'Confirm a decisive claim against instructions or controlled execution.',bridge:'Separate observations from analyst interpretation, as in evidence-based reconstruction.',resource:'ghidra'},
{id:'mitigations',title:'Mitigations & bounded claims',category:'Research',desc:'ASLR, non-executable memory, stack protection, and other mitigations affect program behavior and security analysis. Their presence alone does not prove a program safe.',example:'A sanitizer-reported bounds error establishes a memory defect on that path; it does not establish remote reachability or exploitability.',check:'Describe the tested context and avoid inferring impact you have not demonstrated.',bridge:'Your identity research already distinguishes reachable, justified, and observed behavior.',resource:'asan'},
{id:'evidence',title:'Reproducibility & provenance',category:'Research',desc:'A useful finding ties a precise claim to a known sample, environment, input, observation, and repeatable method.',example:'Keep source and binary hashes, tool versions, compiler flags, inputs, outputs, time zone, and a clean rerun.',check:'Could another person verify this exact claim with the material you preserved?',bridge:'Use Neo4j for provenance relationships, with hypotheses labeled separately.',resource:'gdb'},
{id:"cfg",title:"Control-flow & call graphs",category:"Automation",desc:"A control-flow graph connects basic blocks inside a function. A call graph connects functions. Both are recovered models: indirect jumps and calls leave edges missing or over-approximated.",example:"A function pointer table produces a call site whose targets a direct-call graph does not contain.",check:"For any reachability claim, say which edges were recovered statically, which were observed, and which are unresolved.",bridge:"The same question as identity reachability, with the same trap: a missing edge is not proof of no path.",resource:"ghidragh"},
{id:"fuzzing",title:"Coverage-guided fuzzing",category:"Automation",desc:"A fuzzer mutates inputs and keeps those that reach new code. It finds what its harness, seeds, budget and detectors allow it to find.",example:"Fixing the first crash in a parser often exposes a second defect that the first one was masking.",check:"State harness, seeds, sanitizer, time budget and number of trials with every result.",bridge:"Like a detection rule, a fuzzer is only as good as its visibility. Measure the visibility.",resource:"fuzzer"},
{id:"covmetric",title:"Coverage as evidence",category:"Automation",desc:"Coverage records which code ran. It is useful for finding what was never tested and for comparing campaigns. It does not show that executed code was checked for correctness.",example:"A line with a zero count behind an arithmetic condition tells you where mutation alone is stuck.",check:"Report coverage per trial with its spread. Name the uncovered code you consider important.",bridge:"Comparable to log source coverage in monitoring: necessary to know, never sufficient.",resource:"cov"},
{id:"symex",title:"Symbolic execution & path explosion",category:"Automation",desc:"Symbolic execution treats inputs as unknowns, collects the conditions along each path and asks a solver for values that satisfy them. The number of paths grows quickly with loops and input-dependent branches.",example:"A solver inverts a multiply-and-compare check in seconds; a loop over a symbolic length can stall it.",check:"Treat solver output as a hypothesis. Confirm it by running the real program.",bridge:"A solver model is an inference. Your forensic habit of confirming against the system applies directly.",resource:"angr"},
{id:"evalmethod",title:"Evaluating an analysis tool",category:"Automation",desc:"Automated bug-finding is randomized and target-dependent. A credible evaluation uses repeated trials, a stated baseline, equal budgets, a statistical comparison and ground truth where available.",example:"One 60-second run where tool A beats tool B says nothing. Ten trials each with a reported spread begins to.",check:"What is the baseline, how many trials, and what would count as no difference?",bridge:"The same discipline as evaluating a detector: false positives, false negatives and a fair baseline.",resource:"evalfuzz"},
{id:"triage",title:"Crash triage & deduplication",category:"Engineering",desc:"Many crashing inputs usually reduce to few root causes. Bucketing by stack or error type is a heuristic first pass; root-cause analysis decides.",example:"Five crash files, two buckets: an out-of-bounds read and a stack buffer overflow in the same function.",check:"Could two buckets share one cause, or one bucket hide two? What did you do to find out?",bridge:"Alert deduplication and incident correlation in a SOC are the same problem with different data.",resource:"cwe"},
{id:"hardening",title:"Build hardening as an inventory",category:"Engineering",desc:"Position-independent code, non-executable stacks, RELRO, stack protectors and fortified library calls raise the cost of exploiting memory errors. Whether a binary has them is checkable from the file.",example:"A stripped binary can still show RELRO and PIE, while symbol-based checks may have to answer unknown.",check:"Report yes, no, partial or unknown per property, with the evidence each verdict rests on.",bridge:"Configuration compliance, which you know from administration, applied to compiled artifacts.",resource:"openssf"},
{id:"reachprio",title:"Reachability-based prioritization",category:"Engineering",desc:"A vulnerable function matters more when attacker-influenced input can reach it. Reachability analysis is used to rank findings, and its value depends on how incomplete edges are handled.",example:"A flagged library function that no entry point calls directly may still be reached through a callback.",check:"Does the verdict distinguish not reachable from not shown to be reachable?",bridge:"The direct continuation of identity reachability expansion, moved from accounts to code.",resource:"ssvc"},
{id:"design",title:"Design-oriented research",category:"Engineering",desc:"An engineering doctorate delivers a validated design for a problem in a real context. The work is judged on problem understanding, justified design choices and evidence that the design meets its requirements in that context.",example:"A requirement such as \"an administrator without reverse-engineering training can operate it\" is testable and shapes the design.",check:"Who has the problem, how will you know the design helped, and what would make you stop?",bridge:"Your SME-focused thesis already reasoned from an organization’s constraints. Keep doing that.",resource:"wieringa"},
{id:"cvd",title:"Disclosure & product obligations",category:"Engineering",desc:"Finding a weakness in software you do not own creates duties: authorization before testing, coordinated disclosure after. Manufacturers increasingly have legal obligations for vulnerability handling.",example:"A lab finding in an owned toy program needs none of this. A finding in a vendor firmware image needs all of it before you start.",check:"Before analysis: who authorized it, who will be told, and on what timeline?",bridge:"The chain-of-custody and reporting discipline of forensics, applied before the work begins.",resource:"cra"}
];
