{id:'p5',title:'An evidence graph for analysis',desc:'Represent a sample, build, function, hypothesis, observation, and report in a small provenance graph.',level:'Synthesis',effort:'3–5 sessions (estimate)',tools:'Python · Neo4j',bridge:'Graph modeling, identity reachability, and provenance',deliverable:'Small graph schema + queries backed by source references',limits:'Graph links reflect evidence strength, not automatically established causality.',labs:['static','telemetry'],stage:'s5',icon:'network'},
{id:"p6",title:"Reachability-aware finding triage",desc:"Given binaries and a list of flagged functions, rank the findings by whether an entry point can reach them, with unresolved indirect calls reported as unknown.",level:"Intermediate",effort:"6–10 sessions (estimate)",tools:"Python · objdump or Ghidra headless · Neo4j · GDB",bridge:"Identity reachability graphs from your thesis, applied to call graphs",deliverable:"A small tool, a graph schema and an evaluation on programs where you know the true answer",limits:"Static call graphs are incomplete. Results are a ranking aid, not proof of exploitability or of safety.",labs:["callgraph","static","debug"],stage:"s6",icon:"network"},
{id:"p7",title:"A fair small-scale fuzzing evaluation",desc:"Compare two fuzzing configurations on owned targets using repeated trials, equal budgets and reported variance.",level:"Intermediate",effort:"5–8 sessions (estimate)",tools:"libFuzzer · AFL++ (optional) · llvm-cov · Python",bridge:"Experiment design and statistics from your research work",deliverable:"An evaluation protocol, raw results for every trial and a short write-up",limits:"Toy targets and short budgets. Conclusions do not transfer to real software without a new study.",labs:["fuzz","coverage"],stage:"s6",icon:"activity"},
{id:"p8",title:"Binary hardening inventory for a software estate",desc:"Extract the binaries from an openly licensed firmware image or a Linux package set, audit their hardening properties and present the gaps to a non-specialist owner.",level:"Intermediate",effort:"5–8 sessions (estimate)",tools:"Python · readelf · binwalk · a dashboard or CSV",bridge:"Systems administration, asset inventory and compliance reporting",deliverable:"A repeatable pipeline, an inventory with unknowns and a one-page summary for a decision maker",limits:"Hardening flags are not vulnerability findings. Use only images you are licensed or authorized to analyze.",labs:["hardening","static"],stage:"s7",icon:"shield"},
{id:"p9",title:"From crash to detection content",desc:"For a triaged defect in an owned program, derive what a defender could observe when it is triggered, and write a detection or input filter that does not depend on a specific exploit.",level:"Synthesis",effort:"6–10 sessions (estimate)",tools:"ASan · GDB · Windows or Linux telemetry · optional Security Onion",bridge:"Security monitoring, detection engineering and your SME focus",deliverable:"Root-cause note, a trigger condition, a detection rule and its tested false-positive and false-negative cases",limits:"Shown on a toy program in a lab. Telemetry availability and evasion are open questions.",labs:["crashtriage","telemetry","triage"],stage:"s7",icon:"target"},
{id:"p10",title:"Continuous fuzzing blueprint for a small team",desc:"Design and prototype fuzzing in CI for an owned repository: harness, time budget per change, crash triage and who acts on a finding.",level:"Synthesis",effort:"5–8 sessions (estimate)",tools:"libFuzzer · ClusterFuzzLite or a plain CI job · triage script",bridge:"Operations experience and what a small organization can sustain",deliverable:"A working CI job on your own repository and an operating guide with costs and responsibilities",limits:"Prototype on owned code. Maintenance cost over time is not measured by a prototype.",labs:["fuzz","crashtriage","proposal"],stage:"s7",icon:"layers"}
