const SAFETY = [
['scope','Use owned, benign programs','Start with the supplied toy sources or explicitly authorized training binaries. Preserve source provenance and authorization.'],
['vm','Separate the learning environment','Use a dedicated VM and a non-admin daily account. Host and guest architecture are not yet recorded; confirm x86-64 compatibility.'],
['network','Keep execution isolated','Install tools from official sources first, then disconnect the VM network. Do not use bridged networking for analysis. Host-only links are optional for later controlled telemetry.'],
['sharing','Disable convenience sharing','Turn off shared folders, shared clipboard, drag-and-drop, and unnecessary device passthrough during program execution.'],
['snapshot','Save a clean snapshot','Record the snapshot name, guest OS, tool versions, and date. Keep evidence outside the disposable execution state using a deliberate transfer process.'],
['data','Use synthetic data','No production credentials, customer data, or active malware in this workspace. Use benign data for telemetry and identity context.'],
['limits','Keep experiments bounded','Use fixed toy inputs and resource limits for later fuzzing. Stop, capture evidence, and restore when behavior differs from expectations.']
];
const ENGD = {facts:[["An EngD position in security is expected around the end of 2027 or the beginning of 2028.","Programme correspondence, 5 November 2026"],["Its focus is low-level binary analysis for automated vulnerability research.","Programme correspondence, 5 November 2026"],["No EngD projects on security monitoring were available at the time of the inquiry.","Programme correspondence, 5 November 2026"]],unknowns:["Industry partner and application domain","Target platforms: firmware, embedded, desktop, mobile or other","Expected tooling and languages","Selection criteria and required prior evidence","Opening date, application procedure and funding terms","Whether a candidate may shape the project scope"],competencies:[{id:"c1",title:"Read and reason about machine code",why:"Every automated result has to be checked by someone who can read the instructions.",labs:["branch","abi","static","debug"]},{id:"c2",title:"Find defects automatically",why:"The stated focus. Fuzzing and symbolic execution are the two workhorse techniques.",labs:["fuzz","symbolic","triage"]},{id:"c3",title:"Evaluate tools honestly",why:"A design is only as credible as its evaluation: trials, baselines, variance.",labs:["coverage","crashtriage"]},{id:"c4",title:"Reason over program graphs",why:"Reachability, data flow and patch analysis are graph problems. This is where your thesis transfers.",labs:["callgraph","patchdiff"]},{id:"c5",title:"Engineer for an operating organization",why:"An EngD delivers a design a company can run, not only a technique.",labs:["hardening","repair","proposal"]},{id:"c6",title:"Document reproducibly",why:"Provenance, clean reruns and bounded claims make the portfolio reviewable.",labs:["baseline","report"]}],directions:[{id:"d1",title:"Reachability-aware vulnerability triage for third-party binaries",problem:"Organizations receive more findings about third-party components than they can assess, and most flagged code is never reached in their deployment.",scenario:"A manufacturer or integrator ranks findings in vendor libraries and firmware components before deciding what to patch first.",approach:"Recover call and data-flow graphs from binaries, combine static edges with observed ones, and report a three-valued verdict with the evidence behind it.",validation:"Ground-truth programs where reachability is known, then measure ranking quality and analyst time against an unranked baseline.",bridge:"Directly extends the identity reachability graph work of your Master’s thesis.",risk:"Indirect calls and stripped binaries limit precision. The contribution has to be honest handling of unknowns, not a claim of completeness.",project:"p6"},{id:"d2",title:"Sustainable automated vulnerability discovery for small engineering teams",problem:"Fuzzing and automated analysis are proven at large vendors but rarely survive in small teams: harness upkeep, triage load and unclear ownership.",scenario:"A small product company runs bounded fuzzing on every change and receives deduplicated, classified findings instead of raw crashes.",approach:"A reference pipeline: harness templates, time-boxed campaigns in CI, automatic bucketing and a hand-over format that developers accept.",validation:"Deployment in one real or realistic repository, measured by findings acted on, maintenance hours and developer acceptance.",bridge:"Your thesis targeted SME security posture. Your administration years tell you what such a team can sustain.",risk:"Engineering novelty must be argued from the deployment context. Needs an organization willing to host it.",project:"p10"},{id:"d3",title:"Binary-level assurance evidence for product security obligations",problem:"Manufacturers and buyers must show how product software was built and maintained, often without source code for every component.",scenario:"A manufacturer produces, per firmware release, a verifiable record of component hardening and of whether a published fix is actually present in the shipped binary.",approach:"Automated extraction, hardening audit and patch-presence checking across releases, with every verdict traceable to file evidence.",validation:"Openly licensed firmware across several releases; accuracy of patch-presence verdicts against known source history.",bridge:"Asset inventory and compliance work from systems administration, plus forensic provenance.",risk:"Patch-presence detection across compilers and flags is hard. Scope to one architecture and toolchain family first.",project:"p8"},{id:"d4",title:"From binary root cause to detection content",problem:"Between discovery of a vulnerability and deployment of its patch, defenders need detections or filters, and writing them requires understanding the defect at binary level.",scenario:"A security team turns a triaged crash or a patch diff into an exploit-independent detection or input filter for the exposure window.",approach:"Derive the trigger condition from root cause or patch diff, map it to observable telemetry or input features, and test the resulting rule.",validation:"Owned programs with known defects; measure detection of varied triggers and false positives on benign inputs.",bridge:"Joins the planned position’s focus to your security monitoring background, so neither is abandoned.",risk:"Depends on telemetry that sees the trigger. May fit a monitoring-oriented group better than a binary-analysis one; ask.",project:"p9"}]};
